import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const canvas=document.querySelector('#game');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x171f1e);scene.fog=new THREE.FogExp2(0x171f1e,.025);
const camera=new THREE.PerspectiveCamera(63,innerWidth/innerHeight,.1,180);
scene.add(new THREE.HemisphereLight(0x829c9a,0x1b2019,1.25));const moon=new THREE.DirectionalLight(0xc3d3cc,2.1);moon.position.set(-16,30,10);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);moon.shadow.camera.left=-38;moon.shadow.camera.right=38;moon.shadow.camera.top=38;moon.shadow.camera.bottom=-38;scene.add(moon);
const mat=(color,rough=.9,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const groundMat=mat(0x333b30),dark=mat(0x222a24),wood=mat(0x514b38),stone=mat(0x60645b),bone=mat(0xb9b7a3),uniform=mat(0x525d4d),skin=mat(0x697568),infected=mat(0x56654d),rust=mat(0x713b2f),bright=mat(0xd6ff4f,.35,.15);
const floor=new THREE.Mesh(new THREE.PlaneGeometry(220,220),groundMat);floor.rotation.x=-Math.PI/2;floor.receiveShadow=true;scene.add(floor);
// Broken asphalt lane and its faded markings
const road=new THREE.Mesh(new THREE.PlaneGeometry(7,150),mat(0x252b28));road.rotation.x=-Math.PI/2;road.position.set(1,.012,-15);road.receiveShadow=true;scene.add(road);
for(let z=-82;z<60;z+=9){const stripe=new THREE.Mesh(new THREE.PlaneGeometry(.12,3.8),mat(0x777765));stripe.rotation.x=-Math.PI/2;stripe.position.set(1,.025,z);scene.add(stripe)}
// Cold distant lights
for(let i=0;i<35;i++){const x=(Math.random()-.5)*140,z=(Math.random()-.5)*135;const lamp=new THREE.PointLight(i%3?0x78918c:0xe37c48,Math.random()*1.2+.4,12,2);lamp.position.set(x,1.5,z);scene.add(lamp);const bulb=new THREE.Mesh(new THREE.SphereGeometry(.09,8,6),new THREE.MeshBasicMaterial({color:i%3?0x8ca49b:0xe5824a}));bulb.position.copy(lamp.position);scene.add(bulb)}
function box(parent,x,y,z,sx,sy,sz,material,rx=0,ry=0,rz=0){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.rotation.set(rx,ry,rz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,x,y,z,r1,r2,h,material,segments=7){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
// Fir trees, roadside debris, and a few unmistakable graveyard silhouettes
for(let i=0;i<115;i++){let x,z;do{x=(Math.random()-.5)*120;z=(Math.random()-.5)*110}while(Math.abs(x)<9&&Math.abs(z)<12);const h=2.8+Math.random()*4;const g=new THREE.Group();g.position.set(x,0,z);cylinder(g,0,h*.28,0,.2,.34,h*.56,mat(0x3e382c));for(let k=0;k<3;k++){const cone=new THREE.Mesh(new THREE.ConeGeometry(1.35-k*.27,h*.46,7),mat(k===1?0x303c35:0x26342e));cone.position.set(0,h*(.42+k*.18),0);cone.castShadow=true;g.add(cone)}scene.add(g)}
for(let i=0;i<25;i++){const x=(Math.random()-.5)*48,z=(Math.random()-.5)*42;if(Math.abs(x)<5&&Math.abs(z)<5)continue;const h=.55+Math.random()*.55;box(scene,x,h/2,z,.48,h,.17,stone,0,(Math.random()-.5)*.25,0);box(scene,x,h+.09,z,.35,.18,.2,stone,0,(Math.random()-.5)*.25,0)}
for(let i=0;i<13;i++){const x=(Math.random()-.5)*45,z=(Math.random()-.5)*45;if(Math.abs(x)<7&&Math.abs(z)<7)continue;const crate=new THREE.Group();crate.position.set(x,.35,z);crate.rotation.y=Math.random()*6;box(crate,0,0,0,.85,.7,.8,wood);for(let n=-1;n<=1;n++)box(crate,n*.26,0,.41,.035,.68,.025,stone);scene.add(crate)}
// Player model: practical field kit, shoulder, head, rifle.
const player=new THREE.Group();scene.add(player);const torso= new THREE.Group();player.add(torso);
box(torso,0,1.12,0,.62,.77,.34,uniform);box(torso,0,1.55,0,.56,.14,.35,dark);cylinder(torso,0,1.74,0,.19,.2,.27,skin,8);box(torso,0,1.79,-.08,.32,.13,.31,mat(0x1c2421));box(torso,-.16,1.12,.19,.14,.24,.05,mat(0x9c5e40));
for(const side of [-1,1]){box(torso,side*.37,1.2,0,.2,.56,.22,uniform,0,0,side*.09);box(torso,side*.13,.55,0,.23,.62,.25,dark);box(torso,side*.14,.16,.03,.24,.18,.39,mat(0x242521));}
box(torso,.31,1.08,-.29,.1,.13,.48,mat(0x303933),0,0,-.08);box(torso,.3,1.06,-.53,.1,.1,.48,mat(0x262b28));box(torso,.3,1.08,-.76,.09,.07,.17,mat(0x171b19));
// Player camera rotation and movement
let yaw=0,pitch=-.08,health=100,ammo=12,reserve=84,kills=0,wave=1,aliveTime=0,started=false,gameEnded=false,reloading=false,shotCooldown=0,damageCooldown=0,spawnTimer=1;let currentGoal=5;
const zombies=[],particles=[],keys={};let gameSpeed=1;const v3=(x=0,y=0,z=0)=>new THREE.Vector3(x,y,z);
function addZombie(){const a=Math.random()*Math.PI*2,r=19+Math.random()*15;const g=new THREE.Group();g.position.set(player.position.x+Math.cos(a)*r,0,player.position.z+Math.sin(a)*r);const body=new THREE.Group();g.add(body);box(body,0,1.08,0,.56,.78,.34,infected);box(body,0,1.57,.01,.49,.14,.3,dark);cylinder(body,0,1.76,0,.2,.21,.3,skin,7);box(body,-.065,1.77,.17,.055,.04,.025,rust);box(body,.09,1.8,.17,.055,.04,.025,bright);for(const s of [-1,1]){box(body,s*.35,1.16,0,.18,.57,.21,infected,0,0,s*.14);box(body,s*.14,.55,0,.22,.59,.22,dark,0,0,s*.05);box(body,s*.15,.15,.06,.22,.17,.34,stone)}const z={group:g,body,hp:2+Math.floor((wave-1)/2),speed:.65+Math.random()*.3,phase:Math.random()*6,attack:0};zombies.push(z);scene.add(g)}
const raycaster=new THREE.Raycaster();const center=new THREE.Vector2(0,0);const clock=new THREE.Clock();
function flash(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(flash.timer);flash.timer=setTimeout(()=>t.classList.remove('show'),1500)}
function updateHud(){document.querySelector('#health-value').textContent=Math.ceil(health);document.querySelector('#health-bar').style.width=Math.max(0,health)+'%';document.querySelector('#health-bar').style.background=health<35?'#e65245':'#d6ff4f';document.querySelector('#status').textContent=health<35?'CRITICAL':'STABLE';document.querySelector('#ammo').textContent=String(ammo).padStart(2,'0');document.querySelector('#reserve').textContent=String(reserve).padStart(3,'0');document.querySelector('#wave').textContent=String(wave).padStart(2,'0')}
function endGame(win){if(gameEnded)return;gameEnded=true;document.exitPointerLock?.();document.querySelector('#end-title').textContent=win?'YOU HELD THE LINE.':'YOU DIDN’T MAKE IT.';document.querySelector('#end-title').style.color=win?'var(--acid)':'#e65245';document.querySelector('#end-copy').textContent=win?'Extraction is inbound. Blackpine will remember.':'The infected overran the perimeter. The night takes another one.';document.querySelector('#final-kills').textContent=String(kills).padStart(2,'0');document.querySelector('#final-wave').textContent=String(wave).padStart(2,'0');document.querySelector('#final-time').textContent=timeText(aliveTime);document.querySelector('#end-screen').classList.remove('hidden')}
function timeText(t){return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`}
function reload(){if(!started||reloading||ammo===12||reserve===0||gameEnded)return;reloading=true;document.querySelector('#weapon-state').textContent='RELOADING';flash('RELOADING');setTimeout(()=>{if(!started||gameEnded)return;const n=Math.min(12-ammo,reserve);ammo+=n;reserve-=n;reloading=false;document.querySelector('#weapon-state').textContent='SEMI-AUTO';updateHud()},1050)}
function shoot(){if(!started||gameEnded||shotCooldown>0||reloading)return;if(ammo<=0){flash('MAGAZINE EMPTY — R TO RELOAD');return}ammo--;shotCooldown=.24;updateHud();document.querySelector('#weapon-state').textContent='FIRING';setTimeout(()=>{if(!reloading)document.querySelector('#weapon-state').textContent='SEMI-AUTO'},180);raycaster.setFromCamera(center,camera);const dir=raycaster.ray.direction.clone();let target=null,best=Infinity;for(const z of zombies){const centerZ=z.group.position.clone().add(v3(0,1.1,0));const to=centerZ.clone().sub(raycaster.ray.origin);const along=to.dot(dir);if(along<0)continue;const closest=raycaster.ray.origin.clone().addScaledVector(dir,along);const dist=closest.distanceTo(centerZ);if(dist<.72&&along<best){best=along;target=z}}if(target){target.hp--;makeHit(target.group.position.clone().add(v3(0,1.3,0)),0xff694c);if(target.hp<=0){scene.remove(target.group);zombies.splice(zombies.indexOf(target),1);kills++;document.querySelector('#kill-feed').innerHTML=`<div><b>+ 01</b> INFECTED NEUTRALIZED</div>`+document.querySelector('#kill-feed').innerHTML;while(document.querySelector('#kill-feed').children.length>3)document.querySelector('#kill-feed').lastChild.remove();if(kills>=currentGoal){if(wave>=4){endGame(true)}else{wave++;currentGoal+=5+wave*2;document.querySelector('#objective').textContent=`WAVE ${String(wave).padStart(2,'0')} — HOLD THE PERIMETER`;flash(`THREAT LEVEL ${String(wave).padStart(2,'0')} — THEY’RE COMING`);reserve=Math.min(120,reserve+24);updateHud()}}}}else{makeHit(raycaster.ray.origin.clone().addScaledVector(dir,18),0xb4bf9e)}if(ammo===0)document.querySelector('#weapon-state').textContent='RELOAD REQUIRED'}
function makeHit(pos,color){const p=new THREE.Mesh(new THREE.SphereGeometry(.065,5,4),new THREE.MeshBasicMaterial({color}));p.position.copy(pos);scene.add(p);particles.push({mesh:p,life:.13})}
function startGame(){document.querySelector('#start-screen').classList.add('hidden');started=true;gameEnded=false;canvas.requestPointerLock?.();for(let i=0;i<5;i++)addZombie();flash('PERIMETER BREACHED — HOLD POSITION')}
function reset(){for(const z of zombies)scene.remove(z.group);zombies.length=0;player.position.set(0,0,0);health=100;ammo=12;reserve=84;kills=0;wave=1;currentGoal=5;aliveTime=0;spawnTimer=1;pitch=-.08;yaw=0;gameEnded=false;reloading=false;document.querySelector('#objective').textContent='ELIMINATE THE INFECTED';document.querySelector('#kill-feed').innerHTML='';document.querySelector('#end-screen').classList.add('hidden');updateHud();startGame()}
document.querySelector('#start-button').addEventListener('click',startGame);document.querySelector('#restart-button').addEventListener('click',reset);document.querySelector('#reload-button').addEventListener('click',reload);document.querySelector('#fire-button').addEventListener('pointerdown',e=>{e.preventDefault();shoot()});
